// History reuses immutable media strings instead of copying base64 on every edit.
const historyMediaByData=new Map(),historyMediaByToken=new Map();let historyMediaSequence=0;
function restoreSnapshot(text){return JSON.parse(text,(key,value)=>key==='data'&&typeof value==='string'&&historyMediaByToken.has(value)?historyMediaByToken.get(value):value)}
snapshot=function(){const serialized=JSON.stringify(project,function(key,value){if(key==='data'&&typeof value==='string'&&['image','audio'].includes(this.type)){let token=historyMediaByData.get(value);if(!token){token='@kotoba-media-'+(++historyMediaSequence);historyMediaByData.set(value,token);historyMediaByToken.set(token,value)}return token}return value});history.push(serialized);if(history.length>30)history.shift();const retained=new Set();for(const entry of history)for(const match of entry.matchAll(/"data":"(@kotoba-media-\d+)"/g))retained.add(match[1]);for(const [token,data]of historyMediaByToken)if(!retained.has(token)){historyMediaByToken.delete(token);historyMediaByData.delete(data)}};
